    faq_a_nm_me_card: "Ja. In \"Mijn personage\" (tik op Sky in New Me) heeft elke fase van Sky die je al hebt bereikt een kleine deelknop in de hoek. Die maakt een glazen kaart als afbeelding – Sky die gloeit tegen een nachthemel, de fase, je voornaam, je dag in de reis en je sleutels – en opent het deelmenu, zodat je hem via WhatsApp kunt versturen of de afbeelding kunt bewaren. Het is maar een afbeelding, dus vrienden kunnen het bekijken, maar je Sky niet meenemen.",
