    bag_examples_v2_toast: "🎁 Nieuwe voorbeelden in je tas: cadeau-ideeën, een paklijst voor het hotel en een lijst voor de vlucht ✨",
    faq_a_bag_examples_list: "Een nieuwe tas komt met voorbeelden die je net als al het andere kunt aanpassen of verwijderen: Thuis (boodschappen, recepten, maaltijden deze week), Gezin (kleine momenten, een lijst voor het verjaardagsfeest, clubjes en activiteiten), Ideeën (ideeën voor het weekend, cadeau-ideeën naargelang hoe hecht je met iemand bent, en wat je doet met gespaard geld) en Reizen (plekken waar je heen wilt, paklijst voor de reis, paklijst voor het hotel en een lijst voor vliegen naar het buitenland). Een tas die al bestond krijgt de nieuwste één keer, in zijn eigen vakken.",
    faq_q_bag_examples_list: "Welke voorbeelden zitten er in Mijn tas?",
    faq_a_nm_me1_guide: "Sky – je personage in New Me, in zijn eerste vorm (Sky 1). De eerste keer, direct na het aanmelden, gaat er een portaal van licht open, met fonkelingen rondom, en vliegt Sky eruit, legt in een paar tikken uit wat er komt en blijft daarna bij elke vraag: terwijl de maaltijden worden gekozen, schrijft hij met je mee in zijn boek, en een tik op zijn tip toont een volgende. Aan het eind viert Sky het met je en neemt je mee op een korte rondleiding – en als de rondleiding voorbij is, heeft hij nog één klein moment met je. Ga je halverwege weg – bij de vragen of tijdens de rondleiding – dan is Sky de volgende keer blij je te zien en vraagt hij of je verder wilt gaan waar je was.",
    faq_q_nm_me1_guide: "Wie begeleidt je bij de start van New Me?",
