    shop_win_other: "Anders…",
    shop_win_to: "Tot",
    room_genie_again_no: "Nu even niet",
    room_genie_again_no_msg: "Dan is het tijd om de doelen te bereiken die je al hebt gesteld. Als je bij het volgende aankomt – wacht daar iets op je ✨",
    room_genie_again_q: "Ben je er weer? ✨ Zou je nog iets anders in je leven willen veranderen?",
    room_genie_again_yes: "Ja",
    room_genie_bye: "Tot snel",
    room_genie_rest: "De bosgeest rust nu uit – kom morgen terug ✨",
    faq_a_shop_holidays: "Tik in de Boodschappenlijst op het cadeautje: de feestdagen van je land (zoals ingesteld in Instellingen) verschijnen op volgorde, met hun datums – die elk jaar vanzelf worden berekend. Tik op een feestdag voor een kant-en-klare lijst van wat mensen ervoor kopen; alles is geselecteerd (behalve wat al op je lijst staat), vink uit wat je niet nodig hebt en tik op ‘Toevoegen aan de lijst’. Twee weken voor een feestdag verschijnt bovenaan de lijst een klein kaartje; ✕ verbergt het tot de volgende feestdag.",
    faq_q_shop_holidays: "Hoe werkt ‘Wat te kopen voor de feestdag’?",
    shop_hol_add: "Toevoegen aan de lijst ({n})",
    shop_hol_added: "Toegevoegd aan de lijst: {n}",
    shop_hol_btn: "Wat te kopen voor de feestdag",
    shop_hol_items_title: "{holiday} – wat te kopen?",
    shop_hol_not_now: "Niet nu",
    faq_a_shop_delivery: "Tik in de Boodschappenlijst op het vrachtwagentje: kies wat er in de bezorging zit (alles is geselecteerd), wanneer het komt – vandaag, morgen of een andere dag – en hoe laat (ochtend, middag, avond of ‘Anders…’ voor je eigen tijden). Die producten gaan naar een kaart ‘Onderweg’ bovenaan de lijst, met de dag en de tijden. Als de dag er is, verschijnt ‘Is de bezorging aangekomen?’ in Mijn Dag (en op de kaart staat ‘Aangekomen?’). Is alles er, dan gaan ze naar ‘Opnieuw kopen’. Ontbreekt er iets, tik dan op wat niet is gekomen en het gaat meteen terug op de lijst.",
    faq_a_shop_departments: "De lijst sorteert zichzelf op de afdelingen van de supermarkt – groente & fruit, brood, zuivel & eieren, vlees & vis, voorraadkast, diepvries, dranken, snacks, schoonmaak, verzorging, baby en huisdieren – zodat je de gangpaden op volgorde afloopt. De afdeling wordt herkend aan de naam van het product. Staat een product op de verkeerde plek, tik erop en kies de afdeling, of ‘Overig…’ om zelf een naam te typen.",
    faq_a_shop_share_qty: "Ja. Naast elk product voegt + er eentje toe (×2, ×3…) en haalt − er eentje af. De deelknop bovenaan de Boodschappenlijst stuurt de hele lijst, netjes gesorteerd per afdeling, via WhatsApp, e-mail of als kopie.",
    faq_a_shop_two_buttons: "Allebei betekenen ze ‘gekocht’. ✕ is voor iets wat je één keer koopt – het verdwijnt van de lijst (en wacht in het archief 🗑️ voor het geval het een vergissing was). ↺ is voor dingen die je steeds opnieuw koopt – ze verdwijnen van de lijst en wachten in ‘Opnieuw kopen’: het kleine ↺-knopje naast de prullenbak onderaan de lijst opent het, en één tik daar zet een product terug op de lijst. Via ‘Bewerken’ daarin kun je er een product uit halen. Als je een product toevoegt, verschijnen dingen die je eerder kocht als suggestie, en staat het al op de lijst, dan wordt het gewoon ×2 in plaats van een tweede regel.",
    faq_q_shop_delivery: "Hoe werkt ‘Ik heb een bezorging besteld’?",
    faq_q_shop_departments: "Waarom is mijn boodschappenlijst in afdelingen verdeeld?",
    faq_q_shop_share_qty: "Kan ik een hoeveelheid aangeven of de lijst naar iemand sturen?",
    faq_q_shop_two_buttons: "Wat doen ↺ en ✕ naast een product op de boodschappenlijst?",
