    nm_demo_cap_menu: "Elke maaltijd heeft opties uit het menu, met ongeveer evenveel calorieën",
    nm_demo_cap_saved: "Je opgeslagen maaltijden, met één tik",
    nm_demo_saved_1: "Kaastosti en een salade",
    nm_demo_saved_2: "Yoghurt met granola en fruit",
    nm_demo_title: "Zo werkt een wissel",
    faq_a_new_me_challenge_journal: "Als een uitdaging afloopt – groot, mini of de uitdaging van de week – laat het feestje een knop 📝 Hoe ging het? zien, die een pagina in het uitdagingendagboek opent: hoe het voelde (vijf gezichtjes), wat hielp, wat zwaar was en wat ik meeneem – niets daarvan is verplicht, en het kan ook later. Het dagboek is een diamant in de magische rugzak: elke afgeronde uitdaging met de datum en wat er is geschreven, de nieuwste eerst – tik op een uitdaging om die te lezen, te bewerken of te delen (alleen wat op de pagina staat, wordt gedeeld). Een afgeronde uitdaging krijgt ook een medaille bij de prestaties, onder “Uitdagingen die ik heb afgerond”. Het uitdagingendagboek staat los van het gewone dagboek.",
    faq_q_new_me_challenge_journal: "Wat is het uitdagingendagboek?",
    nm_badges_challenges: "Uitdagingen die ik heb afgerond",
    nm_chj_empty: "Uitdagingen die je afrondt, verschijnen hier",
