    nm_chj_q: "Hoe ging de uitdaging?",
    nm_chj_reflect_btn: "Hoe ging het?",
    nm_chj_save: "Opslaan in het uitdagingendagboek",
    nm_chj_saved: "Opgeslagen in het uitdagingendagboek",
    nm_chj_share_text: "Ik heb een uitdaging afgerond in New Me ✨",
    nm_chj_take: "Wat neem ik mee?",
    nm_chj_title: "Uitdagingendagboek",
    nm_chj_write: "Opschrijven hoe het ging",
    nm_swap_time: "Tijd",
    faq_a_ai_reminder_in_text: "Ja – schrijf hem samen met de taak, bijvoorbeeld “morgen om 17:00 het pakket ophalen, met een herinnering een uur van tevoren”. De herinnering wordt bij de taak zelf opgeslagen: een uur van tevoren, een half uur, de dag ervoor enzovoort, en “herinner me” zonder tijd betekent 10 minuten van tevoren. Een herinnering in de tekst heeft voorrang op het herinneringsveld in hetzelfde venster.",
    faq_q_ai_reminder_in_text: "Kan ik de AI-assistent in hetzelfde verzoek om een herinnering vragen?",
    myday_meals_all_done: "Alle maaltijden van vandaag zijn afgevinkt 🍽️",
    nm_tour_week_text: "Een kleine uitdaging voor de week. Elke dag ✓ – aan het eind een sleutel.",
    books_home_chip: "{title} · blz. {page}",
    books_home_of: "van {total}",
    books_home_off_toast: "Het boek is van het startscherm gehaald",
    books_home_on_toast: "Het boek staat op het startscherm 📖",
    books_home_pin: "Op het startscherm",
    books_home_q: "Op welke pagina ben ik?",
    books_home_save: "Opslaan",
    faq_a_books_home_chip: "Ja. Tik in de Leeshoek, op de kaart van een boek dat je leest, op 📌 Op het startscherm. Onder de begroeting op het startscherm verschijnt een kleine knop met het boek en de pagina – tik erop, typ het nieuwe paginanummer en sla op, en de voortgang wordt bijgehouden (ook in de Leeshoek). Nog een tik op 📌 haalt hem weer weg. Er kunnen meerdere boeken tegelijk staan – voor elk een knop – en op elk apparaat hetzelfde.",
    faq_a_new_me_week_challenge: "Een kleine uitdaging voor één week, die je zelf kiest. In de gang ligt een grote kaart: “Waar wil je deze week aan werken?” – tik erop, kies een gebied (met mezelf, met anderen, leren en groeien, rust, kleine moedige stappen, thuis en routine) en een uitdaging, en kies wanneer die begint. Dezelfde uitdagingen staan ook in het uitdagingenscherm, onder 🌱 Persoonlijke groei. Zet elke dag een ✓ op de kaart (één vrije dag per week), en elke afgeronde week levert een nieuwe sleutel voor de geheime wereld op. “2 pagina’s per dag lezen” wordt vanzelf afgevinkt met de pagina’s die in de Leeshoek zijn vastgelegd. Als de week voorbij is, voegt 📌 Houden als dagelijkse taak de uitdaging toe aan Mijn Routine op het tijdstip dat je kiest, met elke dag een ✓. Er loopt steeds één uitdaging van de week; de grote en de mini-uitdagingen lopen er gewoon naast door.",
    faq_a_room_genie: "Op de veranda aan zee haalt een tik op de lamp van Aladdin de bosgeest tevoorschijn – en er begint een gesprek: wat is je wens (wat zou je in je leven willen veranderen), hoe voelt het als die uitkomt, wat is moeilijk onderweg en hoe kan de situatie van nu ten goede worden gekeerd. Daarna ongeveer hoe lang het gaat duren, een eerste kleine stap en nog twee, en een “als… dan…” voor als het moeilijk wordt. Aan het eind verschijnt de hele wens stap voor stap, en die kan een doel worden in Mijn Doelen (de stappen worden mijlpalen op het pad, met een datum volgens de gekozen tijd; daar kan alles worden aangepast) of worden opgeslagen in het dagboek – en dan neemt de bosgeest afscheid. Er wordt niets opgeslagen als je geen van beide kiest. Vanaf het tweede bezoek vraagt de bosgeest eerst of je nog iets anders in je leven zou willen veranderen: ja – hetzelfde gesprek; nu even niet – een herinnering om de doelen te bereiken die al zijn gesteld. De bosgeest komt één keer per dag tevoorschijn: nadat een wens is opgeslagen (of na “Nu even niet”), rust hij tot morgen. De vragen volgen een bekende manier om een wens in een plan te veranderen: wens, uitkomst, obstakel en plan.",
    faq_q_books_home_chip: "Kan ik mijn boek en pagina op het startscherm zien?",
    faq_q_new_me_week_challenge: "Wat is de uitdaging van de week?",
    faq_q_room_genie: "Wat doet de geest van de lamp?",
