    room_genie_turn_q: "Soms is juist wat moeilijk is ook de kans. Hoe kan de situatie van nu ten goede worden gekeerd?",
    room_sign_text: "Voor mezelf zorgen",
    room_game_tag: "Onderweg – even stoppen en genieten",
    room_drawer_aria: "Klein kastje",
    nm_me_choose: "Kiezen",
    nm_me_on_screen: "Op het scherm",
    faq_a_new_me_game: "In New Me blijven de spelknoppen altijd op dezelfde plek – in de gang, in de geheime kamer en overal in het bos; alleen het schilderij in het midden verandert. Bovenaan: de dag in de reis, sleutels, reeks en de energie van vandaag (hoeveel er van het plan is gegeten), en daaronder de volgende missie – de volgende maaltijd op zijn tijd (een tik opent hem, met ✓ Gegeten). Aan de zijkant: de hele dag, uitdagingen en mijn reis, en daarnaast de uitdaging van de week – de 7 dagen ervan en een ✓ voor vandaag. Onderaan: de magische rugzak (alles in New Me – de wereldkaart, mijn reis, boodschappen, prestaties, uitdagingendagboek, metingen, foto's, de maandkalender, de dagtabel, herinneringen, de menu-pdf en instellingen; hij opent als een eigen scherm). De wereldkaart, het eerste in de rugzak, toont elke plek in het bos – tik op een plek om erheen te gaan; bij een plek op slot zie je hoeveel sleutels er nodig zijn. Sky is je personage op het bospad: hij begint als Sky 1, groeit na een paar uitdagingen (4 sleutels) uit tot Sky 2 en tegen het einde (9 sleutels) tot Sky 3 – met een metamorfose die je ziet gebeuren. Tik op Sky om alle fases te zien – elke fase die al is bereikt kan opnieuw worden gekozen, zodat een eerdere fase terug kan komen. Sky zweeft – sleep hem met je vinger of de muis, en de ingang die hij raakt gaat open (bij een vergrendelde staat hoeveel sleutels er nog missen). Sky gaat ook mee naar elke kamer en elke plek en zweeft waar je hem laat: sleep hem overal naartoe, en sleep de gloeiende ring eronder om hem helemaal rond te draaien; hij kijkt in de richting waarin hij beweegt (op een computer: de pijltjes bewegen hem, Q en E draaien hem). In de gang brengt de kleine 🏠 onder de bovenbalk je terug naar het startscherm; in elke kamer en op elke plek brengt de knop in dezelfde hoek je terug naar de gang.",
    faq_q_new_me_game: "Hoe werken de spelknoppen, de wereldkaart en Sky?",
