    room_magic_song_rec3: "Watervalklokjes",
    faq_a_new_me_menu_build: "Eerst vraagt de vragenlijst welke maaltijden je eet en wanneer (2 maaltijden + een tussendoortje, 2 maaltijden + een licht avondeten, of allebei), en of er 's avonds nog iets is – om te eten of te drinken, wat, en hoe laat. Bij “2 maaltijden + een tussendoortje” zijn de maaltijden lunch (11:30) en avondeten (19:00), met het tussendoortje om 16:00. Daarna verschijnen alle opties voor die maaltijden. Kies per maaltijd tot 2 favorieten – in het menu staat dan “dit of dat”. Bij sommige opties (pita & smeersel, cornflakes met melk, iets lichts) kies je tot 3 dingen die je lekker vindt, elk in een eigen portie, en in het menu staat “dit of dat of dat”; de calorieën volgen wat je kiest. Koffie en drankjes werken net zo. Elke keuze is in balans, zodat de dag precies op 1.300 of 1.500 uitkomt. Op elk moment wijzigen: ⚙️ Instellingen → 🍽️ Stel je menu samen, of “Kies tot 3 die je lekker vindt” op de kaart van de maaltijd.",
