    faq_a_myday_water_toggle: "Ja. Het waterglas in 'Mijn Dag' (met + voor nog een glas) staat standaard aan. Om het te verbergen, zet je “Toon water in 'Mijn Dag'” uit in Instellingen > Personalisatie en kalender. Er wordt niets verwijderd – Waterregistratie blijft werken, en als je de schakelaar weer aanzet komt het glas terug.",
    faq_q_myday_water_toggle: "Kan ik het water in 'Mijn Dag' verbergen?",
    myday_water_toggle_label: "Toon water in 'Mijn Dag'",
    faq_a_routine_newme_sync: "Met New Me heeft het ⚙️ van Mijn Routine een schakelaar 'Synchroniseren met New Me'. Staat hij aan (standaard), dan staan de New Me-maaltijden van vandaag in Mijn Dag en in Mijn Routine – op de plek van de verborgen routinemaaltijden. Staat hij uit, dan verdwijnen de New Me-maaltijden uit allebei en is de routine weer precies zoals hij was. Er wordt niets verwijderd – opnieuw aanzetten brengt alles terug en vraagt welke routinemaaltijden je wilt verbergen.",
    faq_q_routine_newme_sync: "Hoe zet ik de synchronisatie van New Me met Mijn Routine en Mijn Dag aan of uit?",
