    theme_name_watercolor_wash: "Aquarel",
    faq_a_food_list_languages: "De ingebouwde voedingslijst begon met Israëlische gerechten en hun Hebreeuwse namen. In alle andere talen staat elk product onder zijn Engelse naam, en de zoekfunctie vindt elke Engelse naam die ze kent (bijvoorbeeld 'broth' vindt Clear soup); producten met alleen een Hebreeuwse naam staan er niet in. Wat niet in de lijst staat, kun je gewoon in je eigen woorden schrijven – de AI-schatting werkt in elke taal.",
    faq_q_food_list_languages: "Waarom toont de voedingslijst in mijn taal Engelse namen, en minder producten?",
    settings_copyright_line: "© 2026 alle rechten voorbehouden. app ontwikkeld door eden zabari.",
    workout_ready_replace_btn: "Vervangen",
    faq_a_sport_workout_ai: "In Mijn trainingen → ⋯ → Schema met AI (en als de tabel leeg is ook op de tegel naast de kant-en-klare schema's). Antwoord met een paar tikken – hoe vaak per week, wanneer, plek, niveau en doel, bijna allemaal ook met \"Anders\" – en voeg als je wilt een vrije regel toe, zoals een gevoelige knie of 5 km hardlopen voor de zomer. De AI maakt een hele week: soorten training, dagen, tijden, duur, intensiteit, oefeningen en rustdagen. Voordat er iets wordt opgeslagen, zie je een voorbeeld: \"In mijn tabel zetten\" (in plaats van de tabel of erbij), \"Ander voorstel\" (tot 3 keer) of \"Antwoorden wijzigen\". Het schema is bewust gematigd, en als je pijn of een blessure noemt, krijg je rustige opties en het advies om een professional te raadplegen. Het gebruikt hetzelfde AI-tegoed als het rooster en de routine: 5 keer gratis en 60 keer per maand met Premium.",
    faq_q_sport_workout_ai: "Hoe maak ik een trainingsschema met AI?",
