    workout_ai_other: "Anders",
    workout_ai_replace: "In plaats van mijn tabel",
    workout_ai_title: "Trainingsschema met AI",
    workout_ai_when_evening: "Avond",
    workout_ai_when_label: "Wanneer",
    workout_ai_when_morning: "Ochtend",
    workout_ai_when_noon: "Middag",
    workout_ai_when_ph: "bv. na het werk, of 17:30",
    workout_ai_working: "Je schema wordt gemaakt…",
    faq_a_sport_workout_jar: "Elke soort training heeft een eigen gekleurde ster – hardlopen roze, wandelen groen, zwemmen blauw, enzovoort. Elke training die je deze week registreert, uit het schema of los, laat zijn ster in de pot bovenaan Mijn trainingen vallen, en de pot vult zich tot je weekdoel (tik erop om het doel te wijzigen). Haal je het doel, dan gaat de pot stralen. Het kleine potje ernaast telt hoeveel weken op rij je hem vulde.",
    faq_q_sport_workout_jar: "Wat zijn de gekleurde sterren en de pot in Mijn trainingen?",
    faq_a_sport_workout_gcal: "Ja – onder ⋯ → Google Agenda (zodra Google Agenda in Instellingen gekoppeld is). Elke training met een tijd wordt een afspraak die elke week op zijn dagen terugkomt, en wijzigingen in de app werken hem bij. Herinneringen komen alleen uit de app, dus Google voegt er zelf geen toe, en de trainingen verschijnen nooit dubbel in de app. Nog een keer tikken haalt alleen de trainingen uit Google Agenda.",
    faq_q_sport_workout_gcal: "Kunnen mijn trainingen in Google Agenda verschijnen?",
    workout_gcal_btn: "Google Agenda",
    workout_gcal_error: "Google Agenda kon niet worden bijgewerkt – bij de volgende wijziging wordt het opnieuw geprobeerd",
    workout_gcal_not_connected: "Koppel eerst Google Agenda in Instellingen",
    workout_gcal_off_toast: "De trainingen zijn uit Google Agenda gehaald",
    workout_gcal_on_toast: "Je trainingen staan in Google Agenda",
    faq_a_sport_workout_reminder: "Ja – in een training, Herinnering: 10 minuten, 30 minuten of een uur van tevoren, of een eigen tijd (de training heeft een tijd nodig). Hij gaat af zoals je andere herinneringen, één keer en op één plek: in de app als die open is, anders op je telefoon. \"Gedaan\" zet de training in de geschiedenis, en \"Nog niet\" herinnert je over 5 minuten opnieuw.",
    faq_q_sport_workout_reminder: "Kan ik een herinnering krijgen voor een training?",
    workout_reminder_30min: "30 minuten van tevoren",
    workout_reminder_label: "Herinnering",
    workout_reminder_need_time: "Voeg een tijd toe om een herinnering te krijgen",
    faq_a_sport_workout_share: "Onder ⋯ → Delen wordt de week een glazen afbeelding in de kleuren van je thema, met een bescheiden link naar de app (op een telefoon gaat hij meteen naar het deelmenu, op een computer wordt de afbeelding opgeslagen). ⋯ → PDF om te printen opent een overzichtelijke pagina van de hele week, met een vakje om af te vinken naast elke training en oefening – kies \"Opslaan als PDF\" of print hem. Het schema staat ook in het gegevensrapport in Instellingen, bij Sport.",
    faq_q_sport_workout_share: "Hoe deel of print ik mijn trainingsweek?",
    share_image_saved: "De afbeelding is opgeslagen – je kunt hem bijvoegen",
    share_save_image: "Afbeelding opslaan",
    workout_pdf_btn: "PDF om te printen",
    workout_share_btn: "Delen",
    faq_a_sport_workout_board: "Onder ⋯ → Weekbord is elke dag een kolom: sleep een training naar een andere dag (op een telefoon eerst lang indrukken). In een training zet \"Ook in Mijn Routine\" hem op zijn tijd en dagen in je routine, en wijzigingen blijven in beide richtingen gelijk; vanuit een item in Mijn Routine doet \"Toevoegen aan mijn trainingen\" het omgekeerde. Een ✓ op de ene plek telt op beide, en in Mijn Dag staat hij maar één keer – in de chip naast het water.",
    faq_q_sport_workout_board: "Hoe verplaats ik een training naar een andere dag, en koppel ik hem aan Mijn Routine?",
    routine_in_workouts_btn: "Openen in mijn trainingen",
    routine_to_workout_btn: "Toevoegen aan mijn trainingen",
    routine_to_workout_done: "Toegevoegd aan mijn trainingen 💪",
    workout_delete_confirm_routine: "Hij verdwijnt uit het schema en uit Mijn Routine. Trainingen die al in de geschiedenis staan, blijven.",
    workout_moved: "Verplaatst naar {day}",
    workout_routine_need_time: "Voeg een tijd toe om het in Mijn Routine te zetten",
    workout_routine_toggle: "Ook in Mijn Routine",
    workout_view_board: "Weekbord",
    workout_view_timeline: "Tijdlijn",
    faq_a_sport_workout_plan: "In Trainingsregistratie, onder \"Mijn trainingen\": + Training – soort, dagen, tijd, duur, intensiteit en plek (ook \"Anders\"). Kracht-, functionele en zwemtrainingen kunnen een lijst oefeningen hebben, en Rust markeert een rustdag. Je kunt ook met een kant-en-klaar schema beginnen. De training van vandaag staat groot bovenaan, met de hele week eronder; ✓ zet hem met zijn intensiteit in de trainingsgeschiedenis. Onder ⋯ stel je een weekdoel in (trainingen of minuten) – elke training laat zijn ster in de pot vallen.",
    faq_a_sport_workout_today: "In Mijn Dag laat een kleine chip naast het water de training van vandaag zien – een tik opent de details, ✓ en ▶. ▶ start een timer die doorloopt in de chip op het startscherm, en \"Afronden\" registreert de training met de echte tijd. Loopt in New Me de uitdaging \"Twee weken in beweging\", dan telt een geregistreerde training daar vanzelf mee.",
    faq_q_sport_workout_plan: "Hoe plan ik mijn trainingsweek?",
    faq_q_sport_workout_today: "Waar zie ik de training van vandaag, en hoe werkt de timer?",
