    faq_a_new_me_magic_themes: "Vijf sprankelende thema's die bij New Me horen: Betoverd bos, Sterrenstof, Rozenfee, Magisch noorderlicht en Gouden schemer. Kies er een in New Me (⚙️ Instellingen > Kleuren) of in Instellingen > Weergave en scherm, en een glitterpenseel schildert het scherm in dat thema. Een magisch thema voegt glitters toe in de hele app en bij elke tik. Je kunt altijd terug naar elk ander thema.",
