    theme_magic_section_label: "Magische thema's van New Me",
    apptour_focus_text: "Alles gaat opzij behalve dat ene ding voor nu – met een grote ✓. Daarna verschijnt het volgende.",
    apptour_m_presets_text: "Je opgeslagen maaltijden op één plek: zoeken, onlangs gebruikt, per moment van de dag – en ＋ voegt er een toe aan vandaag.",
    apptour_night_text: "🌙 maakt de hele app donker, ☀️ haalt de dag terug.",
    apptour_noteline_text: "Schrijf en tik op ➤ – het wordt bewaard in je notities. 📝 aan het begin schakelt naar 🛒 boodschappen of 🍎 een opgeslagen maaltijd.",
    apptour_search_text: "Notities, boodschappen, agenda, recepten, schriften, doelen, tabellen en boeken – één zoekopdracht vindt alles.",
    faq_a_new_me_ai_menu: "Voor het menu vraagt de vragenlijst welke maaltijden je eet en wanneer (2 maaltijden + een tussendoortje, 2 maaltijden + een licht avondeten, of allebei), of je 's avonds nog iets kleins eet en hoe laat, wat je niet eet en hoe je koffie of thee drinkt. Daarna maakt AI 3 opties voor elke maaltijd – elk zo groot als het deel van die maaltijd van de dag, zodat de dag nog steeds precies op 1.300 of 1.500 uitkomt – plus drankideeën, die als je vaste drankjes worden opgeslagen. Kies per maaltijd tot 2 favorieten; de opties uit het oorspronkelijke menu staan er direct onder, en bij 🔄 Wisselen komen ze na je persoonlijke menu. 🔄 Andere opties maakt een nieuwe set (3 keer per vragenlijst). Antwoorden wijzigen of op elk moment een nieuw menu maken: ⚙️ Instellingen → ✨ Persoonlijk menu (AI).",
    faq_q_new_me_ai_menu: "Hoe werkt het persoonlijke menu van New Me?",
    nm_ai_menu_building: "Er wordt een menu gemaakt voor je maaltijden en tijden…",
    nm_ai_menu_drinks: "Drankjes voor jou",
    nm_ai_menu_error: "Het persoonlijke menu kon nu niet worden gemaakt – hier is het oorspronkelijke menu. Je kunt het opnieuw proberen, of later via ⚙️ Instellingen.",
    nm_ai_menu_original: "Uit het oorspronkelijke menu",
    nm_ai_menu_regen: "Andere opties",
