    apptour_s_gcal_inside_text: "Koppel Google Calendar één keer, en afspraken en taken blijven in beide richtingen gesynchroniseerd.",
    apptour_s_menu_text: "Alles wat je kunt aanpassen staat hier, in vijf groepen. We openen ze 👇",
    apptour_skip_part: "Dit deel overslaan",
    apptour_start: "Rondleiding starten",
    nm_sales_premium: "Inclusief heel Premium",
    nm_unlock_premium: "En heel Premium is ook ontgrendeld.",
    settings_sub_status_newme: "Premium zit inbegrepen in je New Me.",
    room_back_to_shelf: "Naar de plank",
    faq_a_new_me_day_total: "Elke dag komt precies op het plan uit: de maaltijden, ongeveer 150 calorieën voor koffie en drankjes overdag, en wat er voor de avond gekozen is – iets kleins om te eten of iets om te drinken. Kies voor de avond tot 3 die je lekker vindt (bijvoorbeeld een banaan, een yoghurt of 2 stukjes pure chocolade; of kruidenthee, thee met een scheutje melk of warme melk), en hun calorieën gaan van de maaltijden af. Elke keuze balanceert zichzelf: een kleinere of grotere optie, een weggelaten maaltijd, het kleine ontbijt en de kleine maaltijd die erbij hoort, of de avond – het verschil komt bij de maaltijden of gaat ervan af, bij elke naar zijn grootte, en onder elke maaltijd staat hoeveel (+ of −) en wat erbij of eraf kan. Een maaltijd die al is afgevinkt, blijft zoals hij is geregistreerd. In de vragenlijst toont elke maaltijd zijn correctie, en een klein kader toont maaltijden, drankjes, de avond en het totaal. Zin in iets anders die dag? Houd het totaal op evenveel calorieën of minder.",
    faq_q_new_me_day_total: "Hoe komt een New Me-dag precies op 1.300 / 1.500 uit, en waar tellen drankjes mee?",
