    nm_less_line_late: "{n} calorieën in deze maaltijd, voor iets kleins om {time} – bijv. {ideas}",
    nm_swap_balanced: "{n} calorieën verdeeld over de maaltijden, zodat de dag op {plan} uitkomt",
    books_quotes_chip: "Citaten",
    faq_a_book_quotes: "Op de plank in de geheime kamer (Citaten), of via het kleine label 💬 Citaten in de Leeshoek – het is dezelfde lijst. Tik op \"+ Citaat\", schrijf de zin en kies het boek uit je Leeshoek, of typ een andere titel via \"✏️ Overig\"; de auteur is optioneel. ✏️ bewerkt een citaat en 🗑️ verwijdert het. De citaten zijn boekenleggers om doorheen te swipen – 🎨 bovenaan wisselt naar foto's of een muur van kaarten.",
    faq_a_room_wish_jar: "Op de plank in de geheime kamer staat een glazen pot voor dromen. Tik op het potje op de bovenste plank (of Plank > De wensenpot) en schrijf hoe je wilt dat je leven eruitziet – zo wild als je wilt, zonder goed of fout. Elke wens wordt een gevouwen briefje dat in de pot valt. “Trek een briefje” opent er willekeurig een, en elk briefje kun je ook los openen. Vanaf de tweede keer dat je dezelfde wens opent, kun je er een doel van maken en hem in kleine stappen opdelen. Eén keer per week verschijnt zachtjes een briefje met een van je wensen – zonder druk, alleen een herinnering waar je naartoe gaat.",
    faq_q_book_quotes: "Waar bewaar ik citaten uit boeken waar ik van hield?",
    faq_q_room_wish_jar: "Wat is de wensenpot in de geheime kamer?",
