    room_wish_to_goal: "🎯 Maak er een doel van, in kleine stappen",
    room_wish_written: "Geschreven op {date}",
    faq_a_saved_meals_page: "Opgeslagen maaltijden hebben een eigen pagina: Voeding en Meetgegevens > ⭐ Opgeslagen maaltijden (of ⭐ in het menu). De zoekbalk bovenaan vindt een maaltijd op naam of ingrediënt, \"Onlangs gebruikt\" laat zien wat je laatst hebt toegevoegd, en de tabbladen (Ontbijt, Lunch, Avondeten, Soepen…) tonen elk moment van de dag. \"+ Vandaag\" zet een maaltijd in de Dagelijkse Maaltijdtracker van vandaag, op de volgende vrije plek. Tik op een maaltijd om hem te bewerken of te verwijderen, en ＋ bovenaan voegt een nieuwe toe.",
    faq_q_saved_meals_page: "Waar vind en beheer ik mijn opgeslagen maaltijden?",
