    presets_tab_snack: "Snacks",
    presets_tab_soup: "Soepen",
    presets_tab_sweet: "Snoep",
    faq_a_notes_sticky_look: "Notities zijn een korte lijst glazen kaarten – 🎨 bovenaan Notities verandert het uiterlijk van alle Notities: de lijst, de dagknoppen bovenaan en het venster waarin je een notitie schrijft – glas, strakke lijst, systeemkaarten of washitape. Een notitie die je sleept houdt precies haar eigen uiterlijk en kleur. Tik op de tekst van een notitie om haar te openen – daar kun je haar bewerken, de kleuren veranderen en zien wanneer ze voor het laatst geschreven is. Tik op ○ als het klaar is, en × verplaatst haar naar het archief (🗑️ onderaan de lijst haalt haar terug). Sleep haar aan ⠿ om de volgorde te veranderen, onder “Later” of naar een dag bovenaan. ! markeert een notitie als dringend – ze schuift zachtjes omhoog naar de eerste rijen met een klein label “Dringend”; nog een tik haalt het weer weg.",
    faq_q_notes_sticky_look: "Hoe open, bewerk of verwijder ik een notitie?",
    note_to_archive_btn: "Naar archief verplaatsen",
    faq_a_routine_clash: "Staat er op die tijd op dezelfde dagen al iets, dan krijg je twee keuzes: \"Vervangen\" – het nieuwe krijgt die tijd en je kiest een andere tijd voor wat er stond (bij het bewerken van iets bestaands wordt de vorige tijd voorgesteld, zodat ze gewoon wisselen), of \"Allebei\" – ze blijven allebei op dezelfde tijd, de een onder de ander. Zijn de dagen verschillend (bijvoorbeeld zo–do en vrijdag), dan wordt er niets gevraagd.",
    faq_q_routine_clash: "Wat gebeurt er als ik iets in mijn routine zet op een tijd die al bezet is?",
    routine_clash_both: "✌️ Allebei – allebei om {time}",
    routine_clash_move_btn: "Verplaatsen en opslaan",
    routine_clash_move_to: "Naar welke tijd moet \"{title}\"?",
    routine_clash_replace: "🔄 Vervangen – en \"{title}\" naar een andere tijd verplaatsen",
    routine_clash_title: "Om {time} staat al: {title}",
    faq_a_new_me_coffee: "Onder het menu van vandaag staat een korte samenvatting: hoeveel calorieën alle maaltijden van de dag samen zijn, hoeveel er over is voor koffie en drankjes, en knoppen voor de gekozen koffie en drankjes – één tik zet het bij de Drankjes. Bij “Kies tot 3 die je lekker vindt” onder de knoppen (en in de vragenlijst) kies je wat er verschijnt: water / bruiswater, kruidenthee, een lightdrankje, zwart / americano (~5), thee met een scheutje melk (~25), koffie op basis van water met tot 100 ml melk of plantaardige melk (~50), lichte warme chocolademelk, warme melk of gewone koffie / latte (~120).",
    faq_q_new_me_coffee: "Waar voeg ik koffie toe, en hoe weet ik hoeveel er nog over is voor de dag?",
