    nm_late_room_line: "Iets kleins voor het slapen · vandaag nog ~{n} kcal over",
    faq_a_recipe_examples: "Onder je eigen recepten staan voorbeeldrecepten: ontbijt, salades, soepen, hoofdgerechten, bijgerechten, snacks, desserts en veganistische gerechten, elk met de bereidingstijd, de calorieën per portie en hoeveel gram één portie weegt. Tik op een recept om het te openen; \"Opslaan in Mijn Recepten\" maakt je eigen kopie die je kunt bewerken. De categorielabels filteren, en nog eens op hetzelfde label tikken laat alles weer zien.",
    faq_a_recipe_grams: "In een recept staat naast de calorieën \"1 portie ≈ X g\". Vul bij je eigen recepten in het receptformulier \"Gram per portie\" in (en als je wilt de bereidingstijd): allebei zijn optioneel, en de tijd verschijnt op de gekleurde band van het recept.",
