    recipe_saved_example_toast: "Opgeslagen in Mijn Recepten – daar kun je het bewerken",
    recipes_examples_title: "Voorbeeldrecepten",
    faq_a_recipe_scan_multi: "Ja. Tik in \"Recept Toevoegen\" op 📷 en kies één foto of meerdere (maximaal 6; een pdf kan ook). Elke foto verschijnt in een korte lijst waarin je kiest wat erop staat: Alles, Ingrediënten of Bereiding, en \"➕ Nog een foto\" voegt er meer toe. Tik daarna op \"✨ Recept scannen\": de AI voegt alles samen tot één recept, op volgorde en zonder dubbele regels, en het telt als één scan. Meerdere foto's die je kiest via 📷 Foto in de AI-assistent openen hier ook.",
    faq_q_recipe_scan_multi: "Kan ik één recept scannen vanaf meerdere foto's, bijvoorbeeld de ingrediënten en de bereiding apart, of twee pagina's?",
    recipe_scan_add_more: "➕ Nog een foto",
    recipe_scan_part_all: "Alles",
