    recipe_scan_part_steps: "Bereiding",
    recipe_scan_remove_photo: "Foto verwijderen",
    recipe_scan_run_btn: "✨ Recept scannen",
    recipe_scan_too_many: "Maximaal {n} foto's per recept",
    faq_a_note_written_at: "Tik op de tekst van de notitie om hem te openen. Binnenin, onder de tekst, staat wanneer hij voor het laatst is geschreven, met de precieze datum en tijd. Alleen een wijziging in de tekst zelf werkt dit bij: archiveren en terugzetten, afvinken ✓, kleuren of de notitie verplaatsen veranderen het niet.",
    faq_q_note_written_at: "Hoe zie ik wanneer ik een notitie heb geschreven?",
    note_written_at: "Laatst geschreven: {date}",
    faq_a_new_me_month: "In de magische rugzak → Maandkalender: elke dag krijgt een kleur naar hoeveel maaltijden zijn afgevinkt, met de pijlen ‹ › wissel je van maand, en onder de kalender staat het daggemiddelde aan calorieën van die maand. Tikken op een dag laat zien hoeveel maaltijden zijn afgevinkt en hoeveel calorieën er die dag zijn gegeten.",
    faq_q_new_me_month: "Waar zie ik in New Me de maand terug en mijn gemiddelde calorieën?",
    nm_month_avg: "Maandgemiddelde: {kcal} calorieën per dag · dagen met invoer: {n}",
    nm_month_day_empty: "Op deze dag is niets genoteerd.",
    nm_month_day_line: "Afgevinkte maaltijden: {checks} · calorieën: {kcal}",
    nm_extra_line_small: "{n} calorieën voor deze maaltijd, van het kleine ontbijt – bijv. {ideas}",
    faq_a_new_me_small_breakfast: "Een licht ontbijt (ongeveer 170 kcal): een speltpita (tot 100 kcal) met smeersel of kaas, en wat groente – kies tot 3 die je lekker vindt, bijvoorbeeld 1 theelepel chocoladepasta, 1 theelepel pindakaas of een plakje kaas (tot 22% vet). Omdat het klein is, hoort er “Plus een kleine maaltijd” bij op een ander moment (anderhalf uur later, bijvoorbeeld 11:30 → 13:00 – elk ander tijdstip kan ook): nog een pita & smeersel, eiwityoghurt met fruit, rijstwafels met kaas, ontbijtgranen met melk of een halve pita & eieren – tot ongeveer 200 kcal, met een eigen ✓. Wat er dan nog over is, wordt over de andere maaltijden verdeeld, en elke maaltijd laat zien hoeveel erbij kwam, dus het dagtotaal blijft zoals in het plan. Kies het in de vragenlijst, of wissel er met 🔄 alleen voor vandaag naartoe – bijvoorbeeld als het ontbijt laat is.",
    faq_q_new_me_small_breakfast: "Wat is het “kleine ontbijt” in het New Me-menu?",
