    faq_a_ai_icon: "Ja – via Instellingen > Weergave en scherm. De zachte bel is de standaard, en met Premium kun je ook een zwevend brein of een robot kiezen.",
    faq_a_new_me_favorites: "Ja. In de vragenlijst (en bij het opnieuw invullen via de instellingen) kun je tot 2 opties per maaltijd kiezen. De eerste staat in het menu, met daaronder een “of”-regel voor de tweede – erop tikken wisselt alleen voor vandaag naar die optie. En als het ontbijt niet op tijd gegeten is, verplaatst “⏰ Later” het naar later op de dag, zonder dat de calorieën veranderen.",
    faq_a_theme_mode: "Sommige speciale thema's zien er donker het mooist uit – Aquarel, Noorderlicht, Barbie en de twee glitterthema's –, dus als je er een van kiest, schakelt de app naar de donkere modus, en elk ander thema (ook de raket) schakelt naar licht. Zwart en Donkergrijs blijven donker. Je kunt het daarna altijd wijzigen met 🌙 in het menu of met Lichte Modus in de instellingen.",
    faq_a_water_month: "Bij het bijhouden van water. Bij elke invoer in het logboek van vandaag staat het tijdstip waarop die is toegevoegd, en \"Maandtabel\" opent de hele maand: elke dag toont hoeveel liter er is gedronken (✓ als het dagdoel is gehaald), en tikken op een dag toont de invoer van die dag met de tijden.",
    faq_q_ai_icon: "Kan ik het pictogram van de AI-assistent veranderen?",
