    dev_sim_panel_title: "PM – alleen voor jou",
    faq_a_new_me_weight_optional: "Nee. Zowel het huidige gewicht als het streefgewicht in de vragenlijst zijn optioneel. Wordt er later een weging toegevoegd (⚖️ Gewicht in “Mijn reis” in New Me, of in de gewichtstracker), dan telt de voortgang vanaf de eerste.",
    faq_q_new_me_weight_optional: "Moet ik mijn gewicht invullen in New Me?",
    nm_unlock_desc: "Het menu, de uitdagingen en de reis staan klaar – stap voor stap, samen.",
    nm_unlock_title: "New Me ontgrendeld!",
    room_reveal_star: "Er is een nieuwe ster opgelicht in de telescoop op het dak ✨",
    faq_a_room_records: "De platenspeler staat vanaf het begin in de kamer, op de boomstronk naast de leunstoel. De platen openen op YouTube de officiële clips van grote hits van de laatste jaren, en daaronder staan vijf rustige melodieën die hier in de kamer spelen – de plaat draait terwijl ze spelen, en “⏹ Stoppen” zet de muziek uit.",
    faq_a_room_roof_gifts: "Ze komen met de 8e sleutel. Een tik op de telescoop laat je erdoorheen kijken: de nachthemel van dichtbij – sleep (of gebruik de pijltjes) om rond te kijken – en je afgeronde uitdagingen vormen er een sterrenbeeld in, één ster per uitdaging; een tik op een ster laat zien welke het was. Een tik op het kistje opent het – voorlopig is het leeg – en nog een tik sluit het weer.",
    faq_q_room_records: "Wat staat er op de platenspeler in de geheime kamer?",
    faq_q_room_roof_gifts: "Wat zijn de telescoop en de kist op het dak?",
    room_chest_letter: "Een briefje voor jou",
    room_chest_letter_1: "Elke kleine stap op de weg was echt – en elke stap telt.",
    room_chest_letter_2: "Lief zijn voor jezelf hoort bij de weg; het is geen pauze ervan.",
    room_chest_letter_3: "Sommige dagen zijn lichter en andere zwaarder. Er op beide soorten dagen zijn, dat is echte kracht.",
    room_chest_letter_4: "Rusten mag. Rust is ook een stap vooruit.",
    room_chest_letter_5: "Veranderingen die blijven zijn de stille – ze groeien dag na dag.",
    room_chest_letter_6: "Vandaag is een goede dag om trots te zijn – al is het maar een beetje.",
    room_chest_letter_7: "Je hoeft niet alles te doen. Alleen het volgende kleine ding.",
    room_chest_letter_8: "Wat er gisteren ook gebeurde, vandaag is een nieuw begin.",
