    dev_sim_buy: "Alsof het gekocht is – zien hoe alles opengaat",
    dev_sim_lock: "Vergrendelen – zien zoals vóór de aankoop",
    dev_sim_locked_toast: "🔒 Vergrendeld – zo ziet het eruit vóór de aankoop",
    faq_a_new_me_preview: "Ja. De New Me-pagina begint met een korte video van wat er binnen gebeurt: de vragenlijst, de lampen in de gang, de rugzak, de uitdagingen en de sleutels. Daaronder staat alles wat erbij zit, een kijkje in één dag en korte antwoorden.",
    faq_q_new_me_preview: "Kan ik New Me zien voordat ik het koop?",
    nm_trailer_c1: "Een korte vragenlijst – en je menu staat klaar",
    nm_trailer_c2: "Elke maaltijd is een lamp in je gang",
    nm_trailer_c3: "In de rugzak: het menu van vandaag, water en boodschappen",
    nm_trailer_c4: "Een kleine uitdaging gehaald – een sleutel erbij",
    nm_trailer_c5: "En achter elke deur – iets alleen voor jou",
    nm_trailer_end: "Vandaag beginnen, stap voor stap",
    nm_trailer_label: "🎬 Een korte video: wat er in New Me gebeurt",
    nm_trailer_pause: "Video pauzeren",
    nm_trailer_play: "Video afspelen",
    nm_trailer_replay: "Opnieuw bekijken",
    ai_chat_food_edit: "✏️ Calorieën / eiwit aanpassen",
    ai_chat_food_invalid: "Calorieën moeten een getal boven 0 zijn",
    ai_chat_food_updated: "Bijgewerkt:",
    faq_a_ai_chat_food_fix: "Ja. Tik onder het antwoord in de chat op ✏️ Calorieën / eiwit aanpassen, verander de getallen en tik op Opslaan. Alleen wat net is toegevoegd verandert – ook als het bij een tussendoortje kwam dat er al stond. AI kan fouten maken, dus even controleren is slim.",
    faq_a_new_me_home_btn: "Met New Me opent een kleine 💎 naast de focusmodus, bovenaan het startscherm, het menu van vandaag. De maaltijden van vandaag staan ook in Mijn Dag, elk met een ✓.",
    faq_a_routine_item_days: "Ja. Tik op het onderdeel in Mijn Routine en kies de dagen onder 📅 Dagen – bijvoorbeeld alleen maandag tot en met vrijdag. Op de andere dagen staat het niet in Mijn Dag en heeft het geen ✓; in Mijn Routine blijft het staan, vager, met de dagen ernaast. De kaart die na 3 dagen zonder ✓ naar een onderdeel vraagt, telt alleen de eigen dagen van dat onderdeel.",
    faq_q_ai_chat_food_fix: "Kan ik calorieën of eiwit aanpassen nadat de assistent eten heeft genoteerd?",
    faq_q_new_me_home_btn: "Waar staat New Me op het startscherm?",
    faq_q_routine_item_days: "Kan één onderdeel in Mijn Routine alleen op bepaalde dagen staan?",
    routine_item_days_label: "📅 Dagen",
    home_note_meal_ph: "Zoek een bewaarde maaltijd…",
    menu_quick_search: "Snel zoeken",
    nm_times_hint: "Tip: je kunt de laatste tijd invullen waarop je elke maaltijd meestal eet – bijvoorbeeld 9:00 als je vaak rond 8 uur eet.",
    room_game_marquee: "Onderweg – even stoppen en genieten",
    room_sand_erase_aria: "Wrijf om het geschrevene uit te vegen",
    faq_a_home_note_line: "Schrijf in de regel in het midden van het startscherm en tik op ➤ (of Enter) – hij wordt bewaard in Notities. Tik op 📝 aan het begin van de regel en hij wordt 🛒: dan gaat wat je schrijft naar de Boodschappenlijst. Tik nog een keer voor 🍎: typ een paar letters, je passende bewaarde maaltijden verschijnen, en één tik zet er een bij de maaltijden van vandaag. Met 🎤 kun je het gewoon zeggen.",
    faq_a_night_mode: "Open het menu ☰ en tik bovenaan op 🌙 – de hele app wordt donker. ☀️ op dezelfde plek brengt de dag terug. Het staat ook in Instellingen, onder Lichte Modus.",
    faq_q_home_note_line: "Hoe schrijf ik een snelle notitie vanaf het startscherm?",
    faq_q_night_mode: "Hoe schakel ik over naar de nachtmodus?",
    menu_day_mode: "Dagmodus",
    menu_night_mode: "Nachtmodus",
    faq_a_secret_room_yoga: "Aan het eind van het bospad staat een lichtende poort, en daarachter, bij een waterval, zitten de boswezens – Lumi, Puffi, Nixie en Sparklet – op hun matjes in een halve cirkel, en Flora, de yogalerares, zit tegenover hen op het enige matje op de steen. Tik op Flora: ze opent haar ogen, alles komt dichterbij, en het gesprek begint rustig, met tijd om te lezen – Flora vraagt hoe het met iedereen gaat, elk wezen antwoordt in eigen naam (met naast elke regel een klein plaatje van wie er praat), en dan vraagt ze jou hoe het voelt bij de mensen die dicht bij je staan. Het gesprek gaat verder volgens je antwoorden – goede mensen, iemand met wie het moeilijk is, of een beetje alleen zijn. Elke weg eindigt met een kleine missie (die meteen in Mijn Dag kan; als de missie is om iets op te schrijven, is er een plek om het te schrijven, en het wordt bewaard in het magische dagboek) en een houding met drie ademhalingen samen. ↩ gaat een stap terug en ✦ begint een nieuw gesprek. De volgende sleutel opent de waterval: als je op de steen gaat zitten, verdwijnt alles en blijft alleen het geluid van het water over. Als je over de vijver buigt, komt er een vraag uit het water – wat zou je echte ik vandaag doen? – en het antwoord wordt een kleine taak in Mijn Dag. Het is een fijn moment, geen vervanging voor een gesprek met een professional.",
    faq_q_secret_room_yoga: "Wat gebeurt er bij de yoga in het bos?",
    room_back_to_forest: "Terug naar het pad",
    room_back_to_yoga: "Terug naar yoga",
    room_item_waterfall: "De waterval",
    room_waterfall_pool_aria: "Raak het water aan",
    room_waterfall_rock_aria: "Ga op de rots zitten",
    room_yoga_guide_aria: "Praat met Flora",
    yg_g_alone: "Dank je voor het delen. Het overkomt iedereen weleens.",
    yg_g_alone_q: "Wat zou goed voelen, al is het maar een beetje?",
    yg_g_critic: "Kritiek kan lang blijven prikken. Het gaat over één moment – niet over de hele mens.",
    yg_g_end: "Dank je dat je in de kring kwam. Je kunt terugkomen wanneer je wilt.",
    yg_g_gate: "Je mag een grens stellen. Een grens is geen muur – het is een poort.",
    yg_g_good: "Wat mooi 💛 Wie heeft je deze week goedgedaan?",
    yg_g_good_msg: "Goede mensen mag je dat zeggen. Een klein bedankje kan hun hele dag maken.",
    yg_g_hard: "Dank je dat je het zegt. Wat weegt het zwaarst?",
    yg_g_listen: "Niet gehoord worden is vermoeiend. Jouw stem telt, ook als hij zacht is.",
    yg_g_new: "Nieuwe mensen beginnen met een klein hallo. Een cursus, een wandeling, een groep – één stap.",
