    yg_task_good: "Vandaag een klein bedankberichtje sturen",
    yg_task_hard: "Eén zin opschrijven die ik zou willen zeggen",
    yg_task_new: "Eén plek vinden om nieuwe mensen te leren kennen",
    yg_task_old: "Iemand „ik dacht aan je” sturen",
    nm_time_hour: "Uur",
    nm_time_minutes: "Minuten",
    routine_time_taken: "Op dit tijdstip staat al iets: {title}",
    faq_a_new_me_times: "In de vragenlijst aan het begin, en altijd in de instellingen van New Me → “Etenstijden”. Als je routine al etenstijden heeft, worden ze daaruit overgenomen – en de maaltijden van de routine kunnen worden verborgen, met de New Me-maaltijden op hun plek. Zo niet, dan kies je hoeveel maaltijden per dag (2 maaltijden + een tussendoortje / 2 maaltijden + een licht avondeten / 2 maaltijden + een tussendoortje + een licht avondeten) en wanneer elke maaltijd is. Bij “2 maaltijden + een tussendoortje” zijn dat lunch om 11:30, een tussendoortje om 16:00 en avondeten om 19:00 (elk ervan kan worden gewijzigd). Dit zijn je etenstijden overal: in de gang, in Mijn Dag, in Mijn Routine en in de herinneringen. Wat je ook kiest, de calorieën van de dag blijven hetzelfde: wat wegvalt, wordt over de andere maaltijden verdeeld.",
    faq_q_new_me_times: "Hoe stel ik mijn etenstijden in New Me in?",
    nm_times_count: "Hoeveel maaltijden per dag?",
    nm_times_from_routine: "Ja, neem ze uit mijn routine",
    nm_times_hide: "De maaltijden van mijn routine verbergen en de New Me-maaltijden op hun plek tonen",
    nm_times_later: "Later",
    nm_times_manual: "Nee, hier kiezen",
    nm_times_none_found: "Je routine heeft nog geen maaltijden – kies hier hoeveel en wanneer.",
    nm_times_q: "Heeft je routine vaste tijden om te eten?",
    nm_times_saved: "Etenstijden opgeslagen",
    nm_times_title: "Etenstijden",
    faq_a_routine_exact_time: "Ja. Als je de AI een routine met een exacte tijd beschrijft (zoals \"16:10 traden\"), wordt die precies zo opgeslagen – niet afgerond op het hele uur. Alles wat in je routine staat, is altijd op het bord te zien, ook als dat uur niet gekozen is in de uurinstellingen, en bij het weghalen van een uur waar iets in staat, wordt eerst gevraagd. Je kunt een tijd ook met de hand wijzigen: tik in het venster van het item op de tijd en kies het uur en de minuten.",
    faq_q_routine_exact_time: "Kan mijn routine een exacte tijd hebben, zoals 16:10?",
    room_item_sand: "Schrijven in het zand",
    room_item_yoga: "Yoga in het bos",
    room_sand_ph: "Wat zou je willen loslaten?",
    room_sand_write: "Schrijven",
    room_song_1: "Für Elise · Beethoven",
