    faq_a_secret_room_diary: "Alleen jij. De dagboekpagina's worden in je account bewaard, dus ze staan op elk apparaat en niemand anders kan ze zien. Het magische dagboek op het bureau in de geheime kamer opent het, en het dagboek in de muziekhoek ook. Onder de nieuwe pagina staat een ingeklapte maandtabel: een stip markeert elke dag met een pagina, en een tik op een dag opent de pagina's van die dag – daar kun je ook een pagina verwijderen. Zodra het dagboek open is, kan het ook in het hoofdmenu – met de schakelaar in het dagboek zelf of in de instellingen van New Me.",
    faq_a_secret_room_places: "Elke ingang bij de bospoort gaat open met een eigen sleutel. Erachter: de veranda aan zee (op het tafeltje de lamp van Aladdin – één tik en er stijgt een bosgeest uit op in een magische nevel, die rondwervelt en een gesprek over je wens begint – zie “Wat doet de geest van de lamp?”), de gitaar en het dagboek (de gitaar speelt een korte, rustige melodie en stopt vanzelf, en elk van de drie platen die in de boom hangen speelt zijn eigen magische melodie – nog een tik stopt die – en in het dagboek op de boomstronk schrijf je), de ademkamer (een stil meer bij zonsondergang – op het water drijft een lotuslantaarn: tik erop, schrijf een wens, en hij drijft ermee weg, ver terug het meer in; met het toverstafje kun je in het zand schrijven wat je wilt loslaten, en het blijft staan tot je het met je vinger wegveegt) en het bospad (het gaat 's nachts open, en een tik op de lantaarns wisselt naar dag; aan de grote tak hangt een magische schommel, op het bankje kun je zitten, en een tik op het bordje brengt het dichtbij – een bord met zes kleine vragen om af te vinken). Op een gesloten ingang zie je hoeveel sleutels er nog nodig zijn. Aan het eind van het pad leidt een lichtende poort naar de yoga bij de waterval – en vandaar naar de waterval zelf.",
    faq_q_secret_room_diary: "Wie ziet het dagboek?",
    faq_q_secret_room_places: "Wat zit er achter de deuren in de gang?",
