    dev_weather_preview_label: "Voorbeeld – alleen in jouw account:",
    faq_a_ai_chat: "Tik op het bubbeltje en er opent een chat. Kies wat je wilt doen – iets voor de agenda, wat je hebt gegeten, een receptfoto of een nieuwe tabel – of schrijf gewoon, en de assistent snapt het zelf. Je kunt ook op 🎙️ tikken en praten in plaats van typen. Voor de agenda kun je kiezen uit eenmalig, elke week of elke dag. Het antwoord komt in de chat, en van daaruit kun je verder met iets anders of de agenda / wat je at openen.",
    faq_a_new_me_hall: "New Me opent bij de poort van een magisch bos, en elke ingang daar is een plek: de ronde deur in de reuzenboom leidt naar de geheime kamer, de holle boomstam naar de veranda aan zee, het paddenstoelenhuisje naar de gitaar en het dagboek, de kleine wilgenboog naar de ademkamer, de grote wilgenboog naar het bospad, en via de bloemenboog met de ladder klim je naar het sterrendak zodra dat opengaat. Op een gesloten ingang zit een slot. Boven het pad zweeft je personage, Sky, en eromheen zitten de spelknoppen: de volgende missie, de uitdaging van de week, de magische rugzak met heel New Me, de wereldkaart en de hulpmiddelen. Een tik op de sleutels bovenaan legt uit hoe je sleutels verdient.",
    faq_a_new_me_routine_meals: "Als er in New Me maaltijden zijn ingesteld en Mijn Routine ook maaltijden heeft, vraagt New Me of ze verborgen moeten worden, met de New Me-maaltijden op hun plek – zodat niets dubbel verschijnt. Mijn Routine toont dan de New Me-maaltijden op hun tijden, met 💎 en een ✓; een tik op de naam van een maaltijd opent een venster om een andere maaltijd te kiezen of de tijd ervan te wijzigen, meteen daar boven de routine. Er wordt niets verwijderd: ze komen terug via ⚙️ Instellingen van New Me → Maaltijden in de routine, of door “Synchroniseren met New Me” uit te zetten in het ⚙️ van Mijn Routine. Zonder actieve New Me komen ze vanzelf terug.",
    faq_a_room_computer: "Het is een kleine chat die begint met „Hoe gaat je dag tot nu toe?” – goed, druk of zwaar – en stap voor stap met je verdergaat, tot één kleine missie aan het eind (die ook meteen in Mijn Dag kan). Je kunt op de antwoorden tikken of vrij typen – wat je typt wordt gekoppeld aan het antwoord dat het dichtst in de buurt komt. „↩ Terug” gaat één stap terug om anders te antwoorden, en „Nieuwe chat” begint op elk moment opnieuw. Na een drukke of zware dag kun je later die dag terugkomen bij de computer: „Ik ben er weer...” zet het gesprek voort. Het groene lampje onderaan zet de computer uit en aan. Alleen de keuzes worden bewaard, alleen op dit apparaat en alleen tot het eind van de dag.",
    faq_q_ai_chat: "Hoe praat ik met de assistent?",
