    pcx_b3a_r1: "Geen keus, alles moet af",
    pcx_b3a_r2: "Ik probeer een minuutje vrij te maken",
    pcx_b3a_s: "Zelfs 5 minuten helemaal stilstaan brengt 50% van je focus terug.",
    pcx_b3a_t: "Pak nu een groot glas water en ga 3 minuten bij een raam staan of even naar buiten – zonder telefoon.",
    pcx_b3a_tn: "Anker van adem en water",
    pcx_b3b_q: "Werken in de stand „brandjes blussen” kost veel energie aan blussen in plaats van vooruitkomen.",
    pcx_b3b_r1: "Precies, alles lijkt even dringend",
    pcx_b3b_s: "Zodra we 60 seconden stoppen en besluiten wat het belangrijkst is, stopt de planning met ons rond te jagen.",
    pcx_b3b_t: "Stel een vaste eindtijd in voor het werk en de taken van vandaag (bijvoorbeeld 19:00). Wat dan af is – top. Wat niet af is – gaat naar morgen.",
    pcx_b3b_tn: "Trek een grens",
    pcx_b_end1: "We hebben goed werk geleverd. Onthoud: zelfs op een drukke dag geeft één kleine stap je de regie terug.",
    pcx_b_end2: "Een rustige, gefocuste rest van de dag gewenst! En als het later te veel wordt – ik ben er. Kom gewoon terug, dan praten we erover.",
    pcx_b_o1: "Te veel taken en eindeloze lijsten",
    pcx_b_o2: "Een stortvloed aan gedachten, zorgen en ruis in mijn hoofd",
