    pcx_back_hi: "Hoi, fijn je weer te zien 💛",
    pcx_back_resume: "↩ Terug naar ons gesprek",
    pcx_br1_q: "Verrassingen en last-minute wijzigingen zijn het frustrerendst. Het voelt alsof alles wat we hadden opgebouwd door elkaar is gegooid. De nieuwe taak die binnenkwam – moet die echt nu meteen?",
