    pcx_br1_s1: "Oké, geduld. Als het al het andere opzijschuift, ligt de rest officieel stil tot morgen. Zonder schuldgevoel.",
    pcx_br1_s2: "Top. We zetten het op de lijst voor „morgen” en laten het de rust van de avond niet stelen.",
    pcx_br1_t: "Besluit nu meteen welk ene ding er vandaag afvalt, om ruimte te maken.",
    pcx_br1_tn: "Het filter zonder compromissen",
    pcx_br2_q: "Dat is het meest natuurlijke van de wereld. Midden in gekke druk kost zelfs stoppen voor een pauze moeite. Geen reden om boos op jezelf te zijn.",
    pcx_br2_r1: "Klopt, ik bleef maar rennen en nu is de energie op",
    pcx_br2_s: "Als de batterij leeg is, helpt nu geen focus of wilskracht. Je lichaam zegt gewoon dat het moet bijtanken.",
    pcx_br2_t: "10 minuten helemaal stoppen: drink water, plens koud water in je gezicht en ga 3 minuten zitten zonder naar een scherm te kijken.",
    pcx_br2_tn: "Snelle reset",
    pcx_br3_q: "Na uren werken zonder pauze schakelt het brein over op een „noodprotocol” en daalt de productiviteit flink. Het nu forceren kost alleen maar 3 keer zo lang.",
    pcx_br3_r1: "Precies, dezelfde zin gaat 4 keer voor mijn ogen langs",
    pcx_br3_s: "Dat is het duidelijke signaal van je brein: „Ik sluit voor vandaag de winkel.”",
    pcx_br3_t: "In plaats van tegen de vermoeidheid te vechten – rond de dag nu af: schrijf de eerste 2 taken voor morgenochtend op, sluit de tabbladen of de computer en schakel officieel over naar de avondstand.",
    pcx_br3_tn: "Bewust afronden",
    pcx_br_me: "Hoi, ik ben er weer... nog steeds te druk / het is zwaarder geworden",
    pcx_br_o1: "Meer taken en chaos die ik niet had gepland",
