    pcx_br_q: "Wat fijn dat je terug bent. Mooi dat je even stilstond in plaats van op de automatische piloot door te rennen. Wat is er gebeurd sinds we spraken?",
    pcx_break_title: "Pauze voor water en ademhaling 🌬️",
