    pcx_c1_q: "Als je lichaam moe of leeg is, voelt elke kleine taak als een berg beklimmen. Waar laat die vermoeidheid zich nu zien?",
    pcx_c1a_q: "Niets slurpt energie en humeur zo weg als slaaptekort. Is er een manier om een tandje terug te schakelen, of iets warms te drinken?",
    pcx_c1a_r1: "Ik moet doorwerken",
    pcx_c1a_r2: "Ik kan het rustiger aan doen",
    pcx_c1a_s: "Als je op zware vermoeidheid draait, mag wat je van jezelf verwacht naar het absolute minimum.",
    pcx_c1a_t: "Als het kan – 15 minuten met je ogen dicht. Zo niet – plens koud water in je gezicht en drink een groot glas water om even op adem te komen.",
    pcx_c1a_tn: "Powernap of koud water",
    pcx_c1b_q: "Emotionele stress stapelt zich vaak direct op in je lichaam en spieren. Een beetje ontspanning helpt om de vlammen te temperen.",
    pcx_c1b_r1: "De druk zie je echt terug in mijn lijf",
    pcx_c1b_s: "Zodra je lichaam de last loslaat, krijgt je hoofd het signaal dat alles oké is.",
    pcx_c1b_t: "Laat je schouders zakken, adem 3 keer diep in tot in je buik en draai langzaam met je nek.",
    pcx_c1b_tn: "Ontspannende rek",
    pcx_c2_o1: "Het gevoel dat ik niet begrepen word / oneerlijk behandeld word",
    pcx_c2_o2: "Boosheid die nog kookt",
    pcx_c2_q: "Wrijving of moeilijke gesprekken met mensen laten een zware nasmaak achter die de rust van een hele dag kan verpesten. Wat zit je er het meest aan dwars?",
    pcx_c2a_q: "Het gevoel niet gezien of niet begrepen te worden is ontzettend frustrerend. Wil je het hier in woorden kwijt?",
