    pcx_c2a_t: "Herinner jezelf eraan dat de interpretatie van anderen niet de absolute waarheid is – en stuur deze wrok op pauze tot morgen.",
    pcx_c2a_tn: "Emotionele grens",
    pcx_c2b_q: "Boosheid is sterke energie die eruit moet, anders vreet ze ons van binnen op.",
    pcx_c2b_r1: "Ik wil gewoon mijn boosheid kwijt",
    pcx_c2b_s: "Laten we haar er dan veilig uit laten, zonder jezelf pijn te doen.",
    pcx_c2b_t: "Sla op een kussen, maak een stevige wandeling van 5 minuten of schrijf al je boosheid op een vel papier – en scheur het kapot.",
    pcx_c2b_tn: "Lichamelijk ontladen",
    pcx_c3_o1: "Chaos in de planning / een storing in iets waar ik lang mee bezig was",
    pcx_c3_o2: "Een gevoel van falen / iets waar ik aan werkte, lukte niet",
    pcx_c3_q: "Op dagen dat alles misgaat, voel je je machteloos. Wat ging er vandaag vooral mis?",
    pcx_c3a_q: "Als dingen buiten onze macht liggen, is er maar één regel: overschakelen op de „makkelijke overlevingsstand”. Wat kan er voor vandaag worden geschrapt?",
