    pcx_c3a_t: "Kies één taak voor vandaag en laat die officieel los, om wat ademruimte te maken.",
    pcx_c3a_tn: "Schakel een tandje terug",
    pcx_c3b_q: "Teleurstelling doet pijn, vooral na veel moeite. Maar een poging die niet lukte, is gewoon informatie – geen definitie van wie we zijn.",
    pcx_c3b_r1: "Het zit me nog steeds flink dwars",
    pcx_c3b_s: "Het is oké om je rot te voelen. Geef het ruimte, zonder jezelf te bekritiseren.",
    pcx_c3b_t: "Doe nu meteen één klein troostend ding (een warm drankje, een favoriet nummer).",
    pcx_c3b_tn: "Mildheid voor jezelf",
