    pcx_c4_q: "Ook dat heeft volop ruimte. Je hoeft niet altijd uit te leggen waarom, om jezelf wat mildheid en rust te gunnen. Hoe zou je de rest van de dag willen doorbrengen?",
    pcx_c4a_s: "Rust is een geweldige oplader. Je mag vandaag een beetje afstand nemen.",
    pcx_c4a_t: "Zet je telefoon het komende uur op stil of op „Niet storen”.",
    pcx_c4a_tn: "De bubbel",
