    pcx_c4b_t: "Kies één fijn ding voor vanavond (een goede film, een warme douche, een lekkere maaltijd).",
    pcx_c4b_tn: "Een kleine verwennerij",
    pcx_c_end1: "Onthoud: een zware dag is geen zwaar leven – het is maar één bladzijde in een heel boek. Morgen is een nieuwe dag.",
    pcx_c_end2: "Een rustige, zachte avond gewenst. En als je nog meer kwijt wilt, of als het later zwaar wordt – ik ben er. Kom gewoon terug, dan praten we.",
