    dictation_mic_denied: "De microfoon is geblokkeerd – sta hem toe via het 🔒 naast het adres in de browser, of in de instellingen van je telefoon",
    faq_a_dictation: "Ja – tik op de microfoon 🎤 in de hoek van de snelle notitie of een schrijfpagina in je schrift en praat: de woorden verschijnen terwijl je praat, in de taal van de app. Tik nog een keer om te stoppen. De eerste keer vraagt de browser toestemming voor de microfoon. Werkt in Chrome / Android en in Safari op de iPhone. Op een computer heb je een microfoon nodig en een browser zoals Chrome, Edge of Safari – ontbreekt er iets, dan zegt de melding precies wat.",
    faq_q_dictation: "Kan ik praten in plaats van typen?",
    faq_a_secret_room: "Een kamer die alleen van jou is, in New Me – een huis in een reuzenboom. Je ziet één muur tegelijk en draait met de pijlen (of door te vegen). De eerste sleutel komt na een ✓ bij een maaltijd op 3 verschillende dagen en opent de deur – en daarmee de hele kamer: de computer, het spel, de platenspeler, de plank met de bibliotheek erin en de kat. Daarna geeft elke afgeronde uitdaging (ook de uitdaging van de week) een sleutel die de volgende plek opent: het sterrendak, de veranda aan zee, de gitaar en het dagboek, de ademkamer, het bospad met yoga, de waterval en een verrassing op het dak – en de 8e brengt een fles uit de zee, met de brief uit het verleden erin. Als er iets opengaat, wijst een pijl de weg. Het deurtje onderaan de speelkast gaat ook open – voor nu is het kastje erachter leeg. Op het sterrendak valt een aangetikte ster als een vallende ster, en de kat zit op het kussen.",
