    settings_good_things_label: "'3 fijne dingen' 's avonds",
    settings_weather_hint: "Regen, wolken of sneeuw op de achtergrond van het startscherm, naar het weer waar je bent. Je geschatte locatie blijft op dit apparaat en wordt via onze server bij MET Norway opgevraagd.",
    settings_weather_label: "Het weer in de lucht van het startscherm",
    weather_failed: "Het weer kon nu niet worden opgevraagd.",
    weather_location_denied: "Geen toegang tot je locatie – sta het toe in de browserinstellingen en probeer het opnieuw.",
    faq_a_home_focus: "Tik op ◎ bovenaan het startscherm: alles verdwijnt behalve dat ene ding voor nu – wat er dit uur is, of het volgende op de lijst van vandaag – met een grote ✓, plus Snelle Notities. Na de ✓ verschijnt het volgende. Tik bovenaan op 'Focusmodus ✕' om alles terug te halen.",
    faq_a_home_search: "Open het menu ☰ – de zoekbalk staat helemaal bovenaan. Typ minstens 2 letters: de resultaten komen uit je notities, boodschappenlijst, agenda, recepten, schriften (titels en paginatekst), doelen, tabellen en boeken, gegroepeerd per soort – tik op een resultaat om er meteen heen te gaan.",
    faq_a_my_day: "Mijn Dag brengt samen wat vroeger Een Kijkje op Vandaag en Mijn Routine was, op één tijdlijn. Onderaan het startscherm zie je hoeveel er gedaan is, wat nu of hierna komt (met een snelle ✓) en naast de titel een glas water met +1. Tik erop (of veeg omhoog) om de hele dag te openen: bovenaan wat geen tijd heeft, daarna alles per uur – taken, afspraken en vergaderingen uit de kalender, vaste wekelijkse tijden, de routine van vandaag, de kleine stappen van je doelen en New Me-maaltijden – met een lijn voor nu. Filter op Taken, Routine of Afspraken. Een ✓ hier is dezelfde ✓ als overal elders (Mijn Routine, Mijn Doelen, de kalender) en laat een madeliefje in het hoekje opengaan. 'Routine bewerken' opent Mijn Routine (staat ook in het menu), en '＋ Toevoegen voor vandaag' voegt een taak voor vandaag toe. Tikken op de titel \"Mijn Dag\" (of op het streepje bovenaan) sluit het weer.",
    faq_q_home_focus: "Wat is de focusmodus?",
    faq_q_home_search: "Hoe zoek ik in de hele app?",
