    bag_ex_txt_moments: "Kleine dingen die ons deze week blij maakten:\n• Samen een avondwandeling na het eten\n• Een tekening die we cadeau kregen\n• Veel lachen aan tafel",
    bag_ex_txt_recipes: "2 kopjes bloem\n2 eieren\n1½ kopje melk\n1 eetlepel suiker\n\nMeng alles, verhit een pan en bak kleine pannenkoekjes goudbruin.",
