    glib_weekly_label: "De wekelijkse stap:",
    glib_weight_note: "Kies een streefgewicht dat goed voelt – het pad vult zich bij elke weging.",
    premium_benefit_goal_library: "De hele doelenbibliotheek – alle kant-en-klare plannen",
    vision_goal_delete_routine_note: "De onderdelen ervan in Mijn Routine worden ook verwijderd.",
    faq_a_goal_small_steps: "Elk doel in Mijn Doelen is een pad: de mijlpalen die al achter je liggen, de stralende steen van vandaag en de trofee aan het eind. Geef een doel een kleine stap – elke dag, of elke week op een dag die je kiest – iets wat ook op een zware dag lukt, zoals '10 minuten rustig hardlopen'. Alle kleine stappen van vandaag staan bovenaan Mijn Doelen en in Mijn Dag, elk met een snelle ✓, en '✓ Vandaag gedaan' onder het pad van een doel vult de stippen van de laatste 7 dagen. Het briefje 'Op weg naar een 10 · we gaan door' blijft expres bovenaan staan: we hoeven niet perfect te zijn – gewoon elke dag een beetje doen om vooruit te komen.",
    faq_q_goal_small_steps: "Wat zijn kleine stappen, en wat betekent 'Geen 10'?",
