    routine_tpl_workout: "Trainingsdag",
    routine_tpl_study_items: "08:00 Ontbijt\n09:00 Studeren (50 minuten + 10 pauze)\n11:00 Tweede studieronde\n13:00 Lunch + rust\n14:00 Vragen oefenen\n16:00 Wandelen of sporten\n19:00 Stof van vandaag herhalen\n22:00 Op tijd slapen",
    routine_tpl_study: "Studiedag",
