    faq_a_new_me_tour: "Direct na de aankoop en de korte vragenlijst laat een korte rondleiding het spel zien: de bovenbalk, de volgende missie, de uitdaging van de week, de magische rugzak en deur 1 naar de geheime kamer. Je kunt hem altijd opnieuw bekijken via ⚙️ Instellingen > 🧭 Rondleiding New Me – daar kun je ook de volledige naam uit de vragenlijst wijzigen. Vóór de aankoop staat er een 🔒 naast New Me in het menu, en een tik opent een pagina met alles wat erin zit.",
