    nm_cert_stat_badges: "prestaties",
    faq_a_new_me_advanced: "De Geavanceerde modus gaat open met het cadeau, na alle 20 uitdagingen, en is aan of uit te zetten in 🎁 Je cadeau. Hij geeft New Me een gouden look, vrij menu samenstellen – elke wissel toont alle opties zonder caloriegrens – en een scherm 📊 Uitgebreide statistieken: calorieën van de afgelopen 30 dagen ten opzichte van het plan, goede dagen per weekdag, de gewichtstrend met een schatting van wanneer het doel wordt bereikt, de gemiddelden van de avondcheck-in en de geschiedenis van de uitdagingen.",
