    nm_letter_open_btn: "✉️ Brief openen",
    nm_letter_gift_title: "De brief uit het verleden",
    nm_gift_locked_view: "Het cadeau gaat open na alle {n} uitdagingen – nog {left}.",
    nm_gift_intro: "Alle {n} uitdagingen, stap voor stap. Dit lag te wachten:",
    nm_gift_title: "Je cadeau",
    faq_a_new_me_letter_gift: "Aan het begin van New Me (of later, bij Uitdagingen) kun je een brief schrijven aan jezelf in de toekomst. Eenmaal verzegeld kan hij niet meer gelezen of bewerkt worden tot hij opengaat: in de fles uit de zee in de geheime kamer, of aan het eind van alle 20 uitdagingen – waar ook een cadeau wacht.",
    faq_q_new_me_letter_gift: "Wat is de brief uit het verleden?",
    faq_a_new_me_challenges: "🏆 Uitdagingen bevat 20 uitdagingen: 10 grote (zoals 5 dagen zonder suiker, een week zonder koolhydraten of 4 kg afvallen in een maand – elke dag een calorietekort, een training en geen suiker) en 10 mini – kleine gewoontes voor een week, zoals kaneelkoffie zonder suiker. Bij het kiezen van een uitdaging wordt gevraagd wanneer te beginnen: vandaag, morgen, volgende week of een andere datum. Een grote en een mini-uitdaging kunnen tegelijk lopen. De lopende uitdaging staat bovenaan het menu en in Mijn Dag, met een ✓ voor de dag. Elke week uitdaging brengt één vrije dag (🍕) die hem niet breekt, en een dag zonder vinkje telt als vrije dag – vandaag en gisteren kunnen worden afgevinkt. Sommige dagen vinken zichzelf af: een training van 20 minuten in Trainingsregistratie, of de maaltijden uit het menu met ✓. Elke uitdaging heeft een ⓘ met wat precies telt (bijvoorbeeld de volledige lijst met koolhydraten) – in de uitdaging zelf en ernaast in Mijn Dag. Daaronder heeft 🌱 Persoonlijke groei 48 kleine uitdagingen voor één week (die tellen niet mee voor de 20) – zie “Wat is de uitdaging van de week?”.",
    faq_q_new_me_challenges: "Hoe werken de uitdagingen in New Me?",
    nm_letter_too_short: "Nog een paar woorden 🙂",
    nm_letter_quiz_note: "Optioneel – hij kan ook later worden geschreven, bij Uitdagingen.",
    nm_letter_write: "✍️ Brief schrijven",
    nm_letter_sealed_line: "Verzegeld op {date} · gaat open na de {n} uitdagingen",
    nm_letter_sealed_toast: "Verzegeld ✉️ – tot bij de finish",
    nm_letter_seal_note: "Eenmaal verzegeld kan de brief niet worden gelezen of bewerkt tot alle uitdagingen voltooid zijn.",
    nm_letter_seal: "✉️ Brief verzegelen",
    nm_letter_ph: "Waar ik vandaag sta, waar ik naartoe wil, wat ik moeilijk vind met eten, wat ik mezelf bij de finish wil zeggen…",
    nm_letter_intro: "Nu geschreven en verzegeld – hij gaat pas open na alle {n} uitdagingen, om te zien hoeveel er sindsdien veranderd is. Waar sta ik nu? Wat zijn mijn doelen, en wat vind ik moeilijk met eten?",
