    nm_ch_completed_label: "uitdagingen voltooid",
    nm_tile_challenges: "Uitdagingen",
    faq_a_workout_calories: "Ja. Elke training krijgt een schatting van de verbrande calorieën – op basis van soort, duur en je laatste gewicht (bij hardlopen en fietsen ook op basis van snelheid, als er een afstand is ingevuld). Die staat in de trainingslijst en in het maandoverzicht (Verbrand) en wordt opgeteld bij het caloriebudget van die dag: in de Dagelijkse Maaltijdtracker, in Calorie- en Gewichtsmetingen en in de ring van New Me. Het is een schatting, daarom staat er een ~ bij.",
    faq_q_workout_calories: "Tellen trainingen mee in mijn dagcalorieën?",
    faq_a_new_me_flexible_menu: "Ja. In de vragenlijst en in de instellingen kies je hoeveel maaltijden per dag – 2 maaltijden + een tussendoortje / 2 maaltijden + een licht avondeten / 2 maaltijden + een tussendoortje + een licht avondeten – en ➖ op een maaltijdkaart haalt die weg (er blijven er minstens 3); ‘➕ Terugzetten’ haalt hem terug. Hoe dan ook blijven de calorieën van de dag hetzelfde: wat wegvalt, wordt over de andere maaltijden verdeeld, en onder elke maaltijd staat hoeveel erbij kwam en wat erbij past. ✏️ Bewerken op een maaltijd opent de tekst – verander wat je wilt (bijv. zonder brood of met een ei extra) en AI rekent de calorieën en eiwitten opnieuw uit. 🔄 Wisselen biedt opties uit het menu, ⭐ Opgeslagen en ✨ Zelf schrijven; elke wijziging kan alleen voor vandaag of vanaf nu gelden. En aan het eind van ‘De hele dag’ staat ➕ Eten toevoegen – schrijf wat er buiten het menu is gegeten, en AI rekent het uit en telt het bij vandaag op (✕ verwijdert het).",
    faq_q_new_me_flexible_menu: "Kan ik het aantal maaltijden in New Me veranderen, of een eigen maaltijd eten?",
    daily_calorie_mini_burn: "+🔥 {amount} van trainingen",
