    nm_swap_ai_too_big: "Iets meer dan wat er voor vandaag over is – tot ~{n} kcal past. Je kunt het toch noteren – de rest van de maaltijden van vandaag wordt kleiner om het te compenseren – of kies een kleinere portie.",
