    vision_focus_ribbon: "🎯 Doel van de maand",
    vision_tagline: "Grote doelen, kleine stappen.",
    faq_a_app_tour: "De rondleiding opent één keer vanzelf, de eerste keer dat je binnenkomt. Hij begint met zijn delen – tik op een deel om er meteen naartoe te gaan – en laat daarna elk onderdeel van de app zien (het startscherm, de AI-assistent en elk menu-item) en de vijf groepen van Instellingen, elk met een korte uitleg, en kijkt bij sommige ook naar binnen (bijvoorbeeld een voorbeeldpad voor een doel, de tas en Google Calendar). Doorgaan gaat verder, Terug gaat terug, Dit deel overslaan springt naar het volgende deel en ✕ sluit de rondleiding. Je kunt hem altijd opnieuw bekijken via Instellingen > Hulp en gebruik > App-rondleiding, en verdergaan waar je was gebleven. Doorgaan en Terug staan altijd op dezelfde plek onderaan het scherm, en op een computer werken de pijltjestoetsen ook.",
    faq_q_app_tour: "Hoe bekijk ik de app-rondleiding opnieuw?",
    apptour_done_text: "Een vraag? Hulp & Veelgestelde vragen in Instellingen beantwoordt alles, en deze rondleiding staat altijd klaar onder Hulp en gebruik.",
    apptour_done_title: "Dat was het! 🎉",
