    apptour_s_account_text: "Premium, wachtwoord, een persoonlijk PDF-rapport, synchronisatie met Google Calendar en account verwijderen.",
    apptour_s_notifications_text: "Herinneringsmeldingen en hun geluid. '⏰ Nog niet' bij een herinnering werkt als de snoozeknop van een wekker: elke 5 minuten krijg je opnieuw een herinnering.",
    apptour_s_personalization_text: "Land, maaltijden en snacks per dag, wanneer je financiële maand begint en wat er op het startscherm staat.",
    apptour_s_appearance_text: "Taal, lichte of donkere modus, thema's, lettertype, tekstkleur, toegankelijkheid en app-grootte.",
    apptour_m_style_text: "Deze knop zet het menu om naar grote tegels – en terug. Op het startscherm staat er maar één van de twee.",
