    apptour_ai_link: "Een kleine 1 erop is de dagelijkse herinnering ‘wat vandaag belangrijk is’.",
    apptour_ai_text: "Schrijf in gewone woorden en je assistent doet de rest: calorieën bijhouden, plannen in je agenda zetten, een recept van een foto lezen en tabellen maken.",
    apptour_quicknote_link: "📝 en 🛒 openen de volledige lijsten; 🍎 registreert een opgeslagen maaltijd in de Dagelijkse Maaltijdtracker.",
    apptour_quicknote_text: "Schrijf snel iets op – in je Notities of direct op de Boodschappenlijst.",
    apptour_routine_link: "Een gewoonte kan automatisch een training registreren in Trainingsregistratie.",
    apptour_routine_text: "Je dagelijkse routine per uur, in tabbladen (kinderen, studie, werk…). Vink elke dag ✓ af om gewoontes en reeksen op te bouwen; 📅 toont de hele maand.",
    apptour_premium_text: "Ontgrendelt de volledige AI-assistent, thema's, lettertypes, Mijn tas en meer.",
    apptour_note_text: "Een plakbriefje voor de hele week. Via het tandwiel ⚙ binnenin voeg je een checklist van 1–3 regels toe en pas je kleur en stijl aan.",
    apptour_peek_link: "Hier verschijnen taken van de AI, de kalender en Google Calendar en mijlpalen van je doelen – plus de calorieën van vandaag 🔥 en je 🎯 doel van de maand.",
