    menu_switch_to_list: "Naar lijstweergave",
    menu_switch_to_tiles: "Naar tegelweergave",
    faq_a_receipts_total: "Tik in het scherm Facturen / Bonnetjes op 🧮 'Totaal van alle bonnetjes'. Kies van welk jaar tot welk jaar (standaard van het oudste bonnetje tot dit jaar), tik op Berekenen en je ziet het totaal van beide categorieën samen - Huishoudelijke uitgaven en Zakelijke uitgaven - plus het aantal bonnetjes en het totaal per categorie apart.",
    faq_q_receipts_total: "Hoe tel ik alle bonnetjes over een periode op?",
    receipts_total_empty: "Geen bonnetjes in deze jaren.",
    receipts_total_invalid: "Voer een geldig jarenbereik in",
    receipts_total_count: "Bonnetjes: {count}",
    receipts_total_calc_btn: "Berekenen",
    receipts_total_to_year: "Tot jaar",
    receipts_total_from_year: "Van jaar",
    receipts_total_title: "Totaal van alle bonnetjes",
    receipts_total_tile: "Totaal van alle bonnetjes",
    faq_a_quick_note_apple: "De 🍎 naast 📝 en 🛒 in het notitievenster is een snelkoppeling om snel een van je opgeslagen maaltijden toe te voegen aan de Dagelijkse Maaltijdtracker van vandaag. Hij staat standaard aan - heb je hem niet nodig, zet hem dan uit in Instellingen > Personalisatie en kalender ('De 🍎-snelkoppeling naar opgeslagen maaltijden tonen in het notitievenster') en zet hem daar op elk moment weer aan.",
    faq_q_quick_note_apple: "Wat is de 🍎 in het notitievenster, en kan ik die verbergen?",
    settings_quick_note_apple_label: "De 🍎-snelkoppeling naar opgeslagen maaltijden tonen in het notitievenster",
    faq_a_vision_board_today: "Tik in Mijn Doelen onder het pad van een doel (in 'Het plan') op 📅 naast een mijlpaal en kies een datum. Je kunt ook '🔁 Elke week tot het af is' aanzetten – dan komt hij elke week op dezelfde dag terug, tot je hem één keer afvinkt. De mijlpaal verschijnt die dag in Mijn Dag en in de kalender (en in Google Calendar, als die gekoppeld is), en de knop laat zien wanneer hij is ingepland. Een ✓ op de ene plek vinkt hem ook op de andere af en brengt het pad van het doel verder. Tik nog een keer op 📅 om de datum te wijzigen of hem uit de kalender te halen. Verwijder je een eenmalige taak uit de kalender, dan verdwijnt ook de mijlpaal uit het doel; verwijder je één week van een wekelijkse herinnering, dan verdwijnt alleen die week.",
    faq_q_vision_board_today: "Hoe zet ik een mijlpaal van een doel in de kalender (📅)?",
    vision_milestone_already_today: "Deze mijlpaal staat al in de taken van vandaag.",
