    auth_consent_privacy: "Privacybeleid",
    auth_consent_terms: "Gebruiksvoorwaarden",
    auth_consent_label: "Ik heb de {terms} en het {privacy} gelezen en ga ermee akkoord, en ik ben 16 jaar of ouder.",
    nm_bonus_sub: "Een kort stuk over wegen, over je doel heen gaan en uit eten",
