    nm_extras_title: "Vandaag ook gegeten",
    nm_drinks_total: "{n} / ~{kcal} kcal",
    nm_drink_missing: "Vul de naam en de calorieën van het drankje in",
    nm_drink_more: "+ Nog een drankje",
    nm_drink_add: "Toevoegen",
    nm_drink_name_ph: "Drankje (bijv. sap)",
    nm_drinks_hint: "Typ gewoon het drankje – de calorieën worden automatisch berekend en het getal kun je aanpassen.",
    nm_slot_drinks: "Drankjes",
    faq_a_new_me_tracking: "Tik bovenaan in New Me op de volgende missie en dan op ✓ Gegeten om de volgende maaltijd als gegeten te markeren – het hele menu met ✓ bij elke maaltijd staat in De hele dag, aan de zijkant, en de maaltijden van vandaag verschijnen ook in Mijn Dag op het startscherm – een tik daar op een ervan (of de muis erboven) laat precies zien wat je gaat eten, met ✓ en Wisselen. Alles is gesynchroniseerd met de Dagelijkse Maaltijdtracker: maaltijden uit het plan, drankjes en alles wat je elders toevoegt (bijvoorbeeld een koffie via snel toevoegen) worden samen geteld in New Me en in Mijn Dag – niets wat je al hebt ingevuld wordt overschreven, en een ✓ weghalen verwijdert alleen het New Me-deel. Als alle maaltijden van vandaag zijn afgevinkt, volgt er een klein feestje. Onder „Drankjes” noteer je de drankjes van de dag – samen tot ~150 kcal, dus ongeveer 3 drankjes van elk tot ~50 kcal. Typ gewoon de naam van het drankje en de calorieën worden automatisch ingevuld met AI. De twee rijen koffie/thee hebben ook een veld „Melk? Hoeveel?” (bijvoorbeeld „een beetje” of „50 ml”), en de berekening wordt bijgewerkt; het getal kun je vóór het toevoegen en ook daarna aanpassen. Een drankje met naam en calorieën wordt automatisch opgeslagen zodra je verdergaat – op Toevoegen tikken is optioneel. Tik op ☆ naast een drankje om het als vast drankje op te slaan – vaste drankjes verschijnen als knoppen bovenaan de kaart Drankjes, en één tik voegt ze aan de dag toe. ⭐ slaat een maaltijd op als opgeslagen maaltijd. „Dagtabel” laat zien wat je hebt gegeten, met calorieën en eiwit. De kleine 💎 naast de focusmodus, bovenaan het startscherm, opent het direct. Calorie- en eiwitwaarden zijn schattingen van AI en kunnen fouten bevatten. Niet alles opgegeten? Onder een afgevinkte maaltijd haalt „Niet alles opgegeten?” een kwart, de helft of driekwart van de portie eraf – of wat je opschrijft, berekend – en de calorieën van de dag worden bijgewerkt.",
    faq_q_new_me_tracking: "Hoe werken de ✓, het wisselen en de calorieën in New Me?",
    faq_a_new_me_what: "New Me is een apart dagmenuprogramma met twee kant-en-klare plannen – 1.300 of 1.500 calorieën – opgebouwd uit 2 hoofdmaaltijden en 2 tussendoortjes, met 3 opties voor elk. Het bevat heel Premium. Prijs: $11.99 per maand (altijd opzegbaar) of eenmalig $99.99, levenslang. Je opent het via 💎 New Me in het menu. Voor de start is er een korte vragenlijst die begint met een medische disclaimer die je moet accepteren. Het programma is alleen algemene informatie en vervangt geen arts of klinisch diëtist.",
    faq_q_new_me_what: "Wat is New Me en hoe krijg ik het?",
