    calorie_stat_avg_label: "Gem.: {amount}",
    daily_focus_modal_title: "🧠 Wat is het belangrijkste dat je vandaag moet doen?", daily_focus_modal_subtitle: "Antwoord, en het wordt direct toegevoegd aan de planning van vandaag.", daily_focus_input_placeholder: "Vandaag wil ik het liefst", daily_focus_save_btn: "Toevoegen aan planning van vandaag", daily_focus_skip_btn: "Niet nu", daily_focus_missing_text: "Schrijf eerst iets", daily_focus_added_toast: "Toegevoegd aan de planning van vandaag", daily_focus_other_option: "✍️ Anders...",
    daily_focus_c1_d0: "Mijn rustige plek beschermen tegen het lawaai om me heen", daily_focus_c1_d1: "Duidelijke grenzen stellen, met liefde en zonder schuldgevoel", daily_focus_c1_d2: "Verankerd blijven, ook als het om me heen stormt", daily_focus_c1_d3: "Mijn rust en energie als topprioriteit behouden", daily_focus_c1_d4: "Niet de gevoelens en stemmingen van anderen overnemen", daily_focus_c1_d5: "Niet toelaten dat de woorden van anderen mijn eigenwaarde ondermijnen",
    daily_focus_c2_d0: "Luisteren naar wat mijn lichaam en geest nodig hebben", daily_focus_c2_d1: "Genieten van de kleine dingen onderweg", daily_focus_c2_d2: "Vertragen en écht naar mezelf luisteren", daily_focus_c2_d3: "Mezelf ruimte geven om adem te halen tijdens het doen", daily_focus_c2_d4: "Me thuis en in vrede voelen bij mezelf", daily_focus_c2_d5: "Me richten op wat er nu gebeurt, zonder vooruit te rennen",
    daily_focus_c3_d0: "Mijn woorden bemoedigend, geduldig en begripvol houden", daily_focus_c3_d1: "Niets persoonlijk opvatten", daily_focus_c3_d2: "Niets aannemen - gewoon vragen, of loslaten", daily_focus_c3_d3: "Vertrouwen op mijn eigen tempo en pad", daily_focus_c3_d4: "Perfectie loslaten en kiezen voor vooruitgang", daily_focus_c3_d5: "Geduldig zijn met mijn eigen proces",
