    faq_q_daily_focus_prompt: "Wat is die kleine herinnering die vraagt wat vandaag het belangrijkst is om te doen?", faq_a_daily_focus_prompt: "Het is een dagelijkse Premium-herinnering: één keer per dag verschijnt er een kleine „1”-badge op het pictogram van de AI-assistent. Tik op de badge om een ballonnetje te openen dat vraagt wat vandaag het belangrijkst voor je is om te doen, met daarin meteen 5 kant-en-klare suggesties (die veranderen dagelijks en rouleren door een heel jaar aan verschillende thema's, zodat ze fris blijven) plus 'Anders' om zelf iets te schrijven - je kunt er meer dan één kiezen. Tik op Toevoegen, en je keuzes verschijnen als kleine herinneringslabels bovenaan 'Mijn Dag' (het zijn geen taken om af te vinken). Als je het sluit met ✕ of ernaast tikt, vervaagt de badge alleen voor de rest van de dag in plaats van te verdwijnen. Het staat standaard aan, maar je kunt het uitzetten in Instellingen > Personalisatie en kalender. Vandaag niet de dag? Tik op '🌙 Vandaag niet' – het badge verdwijnt tot morgen, daarna komt de vraag gewoon terug. Eén suggestie komt uit je eigen leven – de volgende stap van je doel van de maand of het lezen van vandaag. Elke dag is een nieuwe start.",
